<?php
namespace Tests\Feature;
use App\Models\User; use App\Models\Workspace; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Storage; use Tests\TestCase;
class ApprovalExportTest extends TestCase { use RefreshDatabase;
 private function fixture(): array { Storage::fake('asset_originals'); $u=User::factory()->create(); $w=Workspace::factory()->create(); $w->users()->attach($u,['role'=>'owner']); $a=$this->actingAs($u)->withHeader('Idempotency-Key','lifecycle')->postJson("/workspaces/$w->id/assets",['file'=>UploadedFile::fake()->image('food.png',2,2)])->assertCreated()->json('data.id'); $v=$this->postJson("/workspaces/$w->id/assets/$a/versions")->assertCreated()->json('data.id'); $b="/workspaces/$w->id/assets/$a/versions/$v"; $j=$this->postJson("$b/processing-jobs")->assertCreated()->json('data'); return [$u,$w,$a,$v,$b,$j]; }
 public function test_candidate_lifecycle_exports_candidate_bytes(): void { [$u,$w,$a,$v,$b,$j]=$this->fixture(); $this->actingAs($u)->postJson("$b/approval",['job_id'=>$j['id'],'output_sha256'=>$j['output_sha256']])->assertCreated(); $e=$this->postJson("$b/export")->assertOk()->json('data'); $this->assertSame($j['output_sha256'],$e['artifact_sha256']); $this->assertSame('exported',DB::table('asset_versions')->where('id',$v)->value('status')); $record=DB::table('asset_exports')->where('id',$e['id'])->first(); $this->assertSame($j['output_sha256'],hash('sha256',Storage::disk('asset_originals')->get($record->artifact_key))); }
 public function test_approval_requires_exact_job_and_digest(): void { [$u,$w,$a,$v,$b,$j]=$this->fixture(); $this->actingAs($u)->postJson("$b/approval",['job_id'=>$j['id'],'output_sha256'=>str_repeat('0',64)])->assertStatus(409); $this->postJson("$b/approval",['job_id'=>$j['id']+999,'output_sha256'=>$j['output_sha256']])->assertStatus(409); $this->assertDatabaseCount('asset_version_approvals',0); }
 public function test_corruption_and_unauthorized_fail_closed(): void { [$u,$w,$a,$v,$b,$j]=$this->fixture(); Storage::disk('asset_originals')->put($j['output_key'],'corrupt'); $this->actingAs($u)->postJson("$b/approval",['job_id'=>$j['id'],'output_sha256'=>$j['output_sha256']])->assertStatus(409); $x=User::factory()->create(); $this->actingAs($x)->postJson("$b/approval",['job_id'=>$j['id'],'output_sha256'=>$j['output_sha256']])->assertForbidden(); }
}
